Similarity is cleanly split, so I collapse each skill to a group-by-group table with majority votes and look at its algebra.
```python
import numpy as np, pickle
T=np.load("T.npy")
def groups(t,thr=0.85):
    n=32; S=np.eye(n)
    for i in range(n):
        for j in range(n):
            m=(t[i]>=0)&(t[j]>=0)
            S[i,j]=(t[i][m]==t[j][m]).mean() if m.sum()>0 else 0
    lab=-np.ones(n,int);k=0
    for i in range(n):
        if lab[i]<0:
            lab[i]=k
            for j in range(i+1,n):
                if lab[j]<0 and S[i,j]>=thr: lab[j]=k
            k+=1
    return lab
out={}
for s in range(4):
    la=groups(T[s]); lb=groups(T[s].T)
    na,nb=la.max()+1,lb.max()+1
    G=-np.ones((na,nb),int); noise=0; tot=0
    for i in range(na):
        for j in range(nb):
            v=T[s][la==i][:,lb==j]; v=v[v>=0]
            if len(v):
                c=np.bincount(v); G[i,j]=c.argmax(); noise+=len(v)-c.max(); tot+=len(v)
    out[s]=(la,lb,G)
    print("skill",s,"na",na,"nb",nb,"disagree",noise,"of",tot)
    print(" la",list(map(int,la))); print(" lb",list(map(int,lb)))
    for i in range(na): print("  "+" ".join("%2s"%("." if x<0 else x) for x in G[i]), " n=",(la==i).sum())
pickle.dump(out,open("groups.pkl","wb"))
